/**
 * Generated by `scripts/build-realtime-core.ts --embed` before a standalone
 * build and reset to `null` afterwards. The checked-in `null` keeps ordinary
 * `bun test` / `tsc` runs free of native build artifacts.
 *
 * Do not edit by hand: run `bun run build:realtime-core --embed` instead.
 */
export interface EmbeddedRealtimeCoreAsset {
  /** Imported file path produced by `with { type: 'file' }`. */
  source: string
  /** Platform library file name, used for the private extraction dir. */
  filename: string
  /** Lowercase hex SHA-256 of the library bytes. */
  sha256: string
}

export const embeddedRealtimeCore: EmbeddedRealtimeCoreAsset | null = null
